filtergc.example:
-- Find a function by name and defining script
local fn = filtergc("function", {
    Name = "checkPremium",
    IgnoreExecutor = true
}, true)  -- true = return the first match only

-- Find a table that has specific keys
local data = filtergc("table", {
    Keys = { "Coins", "Level" }
}, true)

oth.hook.example:
oth.hook(targetFunction, function(...)
    local original = oth.get_root_callback()
    return original(...)
end)

raknet.add_send_hook.example:
raknet.add_send_hook(function(packet)
    print("sending packet id", packet.Id)
end)

setrawmetatable.example:
local proxy = newproxy(true)
setrawmetatable(proxy, {
    __index = function(_, key)
        return "you asked for " .. tostring(key)
    end
})
print(proxy.anything)  -- you asked for anything

setthreadidentity.example:
local previous = getthreadidentity()
setthreadidentity(2)          -- behave like a normal LocalScript
local ok = pcall(function()
    return game:GetService("CoreGui")
end)
setthreadidentity(previous)   -- always restore
